import { useState } from 'react';
import { useNavigate, Link, useLocation } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import styles from './Auth.module.css';

function AuthHero() {
  return (
    <aside className={styles.hero}>
      <div className={styles.brand}>
        <span className={styles.brandMark}>F</span>
        <span className={styles.brandName}>Finbric</span>
      </div>
      <span className={styles.eyebrow}>Community finance platform</span>
      <h1 className={styles.heroTitle}>Manage money together.</h1>
      <p className={styles.heroText}>
        Create groups for your community and manage shared loans, investments, and member balances in one place.
      </p>
      <div className={styles.featureList}>
        <div className={styles.featureItem}>
          <span className={`${styles.featureIcon} ${styles.featureIconDebt}`}>👥</span>
          <div>
            <p className={styles.featureTitle}>Community groups</p>
            <p className={styles.featureText}>Create a group, invite members, and keep finances organized together.</p>
          </div>
        </div>
        <div className={styles.featureItem}>
          <span className={`${styles.featureIcon} ${styles.featureIconInvest}`}>💸</span>
          <div>
            <p className={styles.featureTitle}>Group loans</p>
            <p className={styles.featureText}>Track loans issued to members and monitor repayments across the group.</p>
          </div>
        </div>
        <div className={styles.featureItem}>
          <span className={`${styles.featureIcon} ${styles.featureIconPlan}`}>📊</span>
          <div>
            <p className={styles.featureTitle}>Shared balances</p>
            <p className={styles.featureText}>See contributions, investments, and what each member owes or holds.</p>
          </div>
        </div>
      </div>
    </aside>
  );
}

export default function Login() {
  const { login } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const [form, setForm] = useState({ username: '', password: '' });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const successMessage = location.state?.message || '';

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);
    try {
      await login(form.username, form.password);
      navigate('/finbric');
    } catch (err) {
      setError(err.response?.data?.message || 'Invalid username or password');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.page}>
      <div className={styles.backgroundOrbOne} />
      <div className={styles.backgroundOrbTwo} />

      <div className={styles.shell}>
        <AuthHero />

        <section className={styles.card}>
          <span className={styles.cardEyebrow}>Welcome back</span>
          <h2 className={styles.title}>Sign in to Finbric</h2>
          <p className={styles.subtitle}>Access your debts, investments, and financial overview.</p>

          {successMessage && <p className={styles.success}>{successMessage}</p>}
          {error && <p className={styles.error}>{error}</p>}

          <form onSubmit={handleSubmit} className={styles.form}>
            <div className={styles.field}>
              <label htmlFor="username">Username</label>
              <input
                id="username"
                name="username"
                type="text"
                value={form.username}
                onChange={handleChange}
                placeholder="Enter your username"
                autoComplete="username"
                required
              />
            </div>
            <div className={styles.field}>
              <label htmlFor="password">Password</label>
              <input
                id="password"
                name="password"
                type="password"
                value={form.password}
                onChange={handleChange}
                placeholder="Enter your password"
                autoComplete="current-password"
                required
              />
            </div>
            <button type="submit" className={styles.primaryButton} disabled={loading}>
              {loading ? 'Signing in...' : 'Sign in'}
            </button>
          </form>

          <p className={styles.link}>
            <Link to="/forgot-password">Forgot password?</Link>
          </p>
          <p className={styles.link}>
            New to Finbric? <Link to="/register">Create an account</Link>
          </p>
        </section>
      </div>
    </div>
  );
}
